internal object DuaKoDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Ruku & Sujood)", "(알라는) 가장 영광스럽고 가장 거룩하며 천사와 성령의 주님 (Jibril)입니다.", "루쿠와 수주드에서.", "선지자 ﷺ은 루쿠(ruku)와 수주드(sujood)로 이것을 낭송했습니다."),
        "dua_sujood_dhanbi_kullah" to DuaText("인수주드: 내 모든 죄를 용서하소서", "오 알라, 작은 것과 큰 것, 처음과 마지막, 공개된 것과 숨겨진 것 등 나의 모든 죄를 용서해 주십시오.", "수주드에서.", "부복은 듀아가 응답되는 곳입니다."),
        "dua_sujood_ridaka" to DuaText("당신의 기쁨으로 피난처", "오 알라, 나는 당신의 분노로부터 당신의 기쁨을 구하며 당신의 형벌로부터 당신의 용서를 구하며 당신에게서 피난처를 구합니다. 나는 당신을 온전히 찬양할 수 없습니다. 당신은 당신 자신을 칭찬하신 그대로입니다.", "수주드에서 — 아이샤 (RA)은 예언자 ﷺ이 이렇게 말하는 것을 들었습니다.", "예언자 ﷺ의 수쥬드 두아."),
        "dua_tashahhud" to DuaText("타샤흐드어(앗-타히야트)", "모든 언어적, 육체적, 재정적 예배 행위는 알라를 위한 것입니다. 예언자여, 당신에게 평화와 알라의 자비와 그분의 축복이 있기를 빕니다. 우리와 알라의 의로운 종들에게 평화가 있기를 바랍니다. 나는 알라 외에는 누구도 숭배받을 권리가 없음을 간증하며, 무함마드 ﷺ이 그분의 종이자 사도임을 간증합니다.", "앉을 때마다 – Abdullah ibn Mas'ud (RA)(Hanafi 관행)이 나레이션을 했습니다.", "예언자 ﷺ은 그것을 꾸란의 수라처럼 가르쳤습니다."),
        "dua_sajdah_tilawah" to DuaText("암송의 사즈다", "내 얼굴은 그것을 창조하시고 그의 능력과 능력으로 듣고 보게 하신 이에게 경배하였나이다.", "암송의 절에서.", "선지자 ﷺ은 밤에 낭송하며 절하면서 이렇게 말했습니다."),
        "dua_after_witr" to DuaText("위트르 이후", "지존하신 왕께 영광을 돌립니다.", "witr의 살람 이후 세 번, 세 번째로 목소리를 높였습니다.", "예언자 ﷺ은 witr 이후에 이렇게 말했습니다."),
        "dua_tahajjud_nur" to DuaText("Tahajjud 개회 간구", "오 알라, 당신께 찬양이 있습니다. 당신은 하늘과 땅과 그 안에 있는 모든 것을 유지하시는 분이십니다. 당신께 찬양이 속합니다. 당신은 하늘과 땅과 그 안에 있는 모든 것의 빛이십니다. 당신께 찬양이 속합니다. 당신은 진리이시며, 당신의 약속은 참되고, 당신과의 만남은 참되고, 당신의 말씀은 참되고, 천국은 참되고, 지옥도 참되고, 선지자들도 참되고, 무함마드 ﷺ도 참되고, 시간도 참됩니다.", "밤 기도(tahajjud)(두아의 시작 부분)를 시작할 때.", "예언자 ﷺ은 tahajjud를 위한 상승에 대해 이것을 낭송했습니다(전체 dua는 al-Bukhari에 있습니다)."),
        "dua_rabba_jibrail" to DuaText("분쟁 문제에 대한 안내", "오 알라, 지브릴의 군주, 미카일과 이스라필, 하늘과 땅의 창조자, 보이지 않는 것과 보이는 것을 아는 분! 당신은 당신의 종들 사이의 차이점을 판단하실 것입니다. 당신의 허락으로 저를 진리로 인도해 주십시오. 참으로 당신은 당신이 원하는 사람을 올바른 길로 인도하십니다.", "tahajjud가 시작될 때 - 불일치 속에서 진실로 인도하기 위해.", "선지자 ﷺ은 이 두아로 밤 기도를 시작했습니다."),
        "dua_going_to_mosque_nur" to DuaText("모스크에 가다(빛의 두아)", "오 알라, 내 마음에 빛을, 내 눈에 빛을, 내 귀에 빛을, 내 오른쪽에 빛을, 내 왼쪽에 빛을, 내 위에 빛을, 내 아래에 빛을, 내 앞에 빛을, 내 뒤에 빛을 주소서.", "Fajr를 위해 모스크에 가는 동안.", "선지자 ﷺ은 기도하러 나갈 때 이것을 낭송했습니다."),
        "dua_waswasa_salah" to DuaText("살라(킨자브) 중 와와사", "나는 저주받은 자 샤이탄에게서 알라께 피난처를 구합니다.", "기도 중에 사탄의 속삭임이 오면 피난처를 찾아 왼쪽으로 가볍게 세 번 침을 뱉으십시오.", "Uthman ibn Abil-'As (RA)이 이것을 했고 속삭임은 사라졌습니다."),
        "dua_alimal_ghayb" to DuaText("보이지 않는 것을 아는 자", "오 알라, 보이지 않는 것과 보이는 것을 아시는 분, 하늘과 땅의 창조자, 만물의 주님이시며 주권자이시여! 나는 당신 외에는 신이 없음을 간증드립니다. 나는 내 자신의 악과 샤이탄의 악과 그의 (부름) 회피로부터 당신께 피난처를 구합니다.", "아침, 저녁, 잠들기 전 — 예언자 ﷺ이 아부 바크르 (RA)에게 가르쳤습니다.", "자신과 샤이탄의 악으로부터 보호합니다."),
        "dua_fitratil_islam" to DuaText("이슬람의 피트라(Fitrah) 위에서", "우리는 이슬람의 피트라, 성실의 말씀, 우리 예언자 무함마드(ﷺ)의 종교, 그리고 정직하고 무슬림이었으며 다신교도가 아니었던 우리 아버지 이브라힘((AS))의 길로 아침을 맞이했습니다.", "아침에.", "아침마다 믿음을 새롭게 합니다."),
        "dua_amsayna_fitrah" to DuaText("이슬람의 피트라(Fitrah) 저녁", "우리는 이슬람의 피트라, 성실의 말씀, 우리 예언자 무함마드(ﷺ)의 종교, 그리고 정직하고 무슬림이었으며 다신교도가 아니었던 우리 아버지 이브라힘((AS))의 길을 따라 저녁에 들어섰습니다.", "저녁에.", "매일 저녁 믿음을 새롭게 합니다."),
        "dua_tahleel_10_fajr" to DuaText("파즈르(Fajr)와 마그리브(Maghrib) 이후의 10 탈렐", "어떠한 동반자도 없는 유일한 알라 외에는 경배받을 분이 없습니다. 통치권은 그분에게 있고 찬양도 그분에게 있습니다. 그분은 생명도 주시고 죽음도 일으키시며, 만물을 다스리는 권세를 갖고 계십니다.", "Fajr(및 Maghrib) 이후 10번, 앉거나 말하기 전에 이동합니다.", "열 가지 선행, 열 가지 죄가 지워지고, 열 등급이 오르며, 하루 종일 샤이탄으로부터 보호를 받습니다."),
        "dua_la_hawla_kanz" to DuaText("잔나의 보물", "알라 외에는 힘도 없고 능력도 없습니다.", "종종, 항상.", "그것은 천국의 보물 중 하나입니다."),
        "dua_four_beloved_words" to DuaText("가장 사랑받는 네 가지 단어", "알라에게 영광을 돌리십시오. 모든 찬미는 알라를 위한 것입니다. 알라 외에는 누구도 숭배받을 권리가 없으며 알라는 가장 위대하십니다.", "알라에게 가장 사랑받는 말.", "선지자 ﷺ에게는 그것들이 태양이 떠오르는 모든 것보다 더 소중합니다."),
        "dua_two_light_words" to DuaText("혀에 빛이 나는 두 단어", "알라에게 영광을 돌리고 모든 찬양은 그분의 것입니다. 위대하신 알라께 영광을 돌립니다.", "혀에는 가볍고 저울에는 무겁습니다.", "가장 자비로우신 분의 사랑을 받으며 혀는 가볍고 저울은 무겁습니다. (알-부카리의 마지막 하디스)"),
        "dua_ya_dhal_jalal" to DuaText("야 달 잘랄리 월 이크람", "오 위엄과 명예를 가지신 분이시여!", "선지자의 ﷺ 지시인 두아(dua)를 붙잡으십시오.", "선지자 ﷺ은 다음과 같이 말했습니다: 'Ya Dhal-Jalali wal-Ikram'을 붙잡으십시오."),
        "dua_sleep_wadatu_janbi" to DuaText("당신의 이름으로 나는 누웠습니다", "나의 주님, 당신의 이름으로 나는 내 옆에 누웠고, 당신의 이름으로 일어섰습니다. 당신이 내 영혼을 취하시거든 자비를 베풀어 주시고, 놓아 주신다면 당신의 의로운 종들을 보호하시듯이 그것을 보호해 주십시오.", "침대의 먼지를 털고 누운 후.", "잠들기 전에 자신의 영혼을 알라에게 맡기는 것."),
        "dua_sleep_khalaqta_nafsi" to DuaText("당신은 내 영혼을 창조했습니다", "오 알라, 당신은 내 영혼을 창조하셨고 그것을 차지하실 것입니다. 그 죽음과 생명은 당신에게 속합니다. 살려두시면 보호해 주시고, 죽게 하신다면 용서해 주십시오. 오 알라, 나는 당신에게 행복을 요청합니다.", "잠들기 전 — Ibn Umar (RA) 내레이션.", "선지자 ﷺ은 취침 시간에 이렇게 말하라고 지시했습니다."),
        "dua_sleep_atamana" to DuaText("잠들기 전 감사", "모든 찬양은 우리에게 먹을 것을 주시고, 마실 것을 주시고, 풍족하게 하시고, 피난처를 주신 알라께 있습니다. 그들을 만족시켜줄 사람이나 피난처를 제공해 줄 사람이 아무도 없는 사람들이 얼마나 많은가.", "잠자리에 들 때.", "선지자 ﷺ은 잠자리에 들 때 이렇게 말했습니다."),
        "dua_sleep_rabbas_samawat" to DuaText("하늘의 제왕 — 빚을 갚으세요", "오 알라, 하늘과 땅과 강력한 보좌의 주인이시며, 우리의 주님이자 만물의 주인이시며, 씨앗과 날짜석을 쪼개는 분이시며, 토라와 인질과 푸르칸의 계시자이시여! 나는 당신이 앞잡이를 잡은 모든 것의 악으로부터 당신께 피난처를 구합니다. 오 알라, 당신은 첫 번째입니다. 당신 앞에는 아무것도 없습니다. 당신은 마지막입니다. 당신 뒤에는 아무것도 없습니다. 당신은 가장 명백하신 분입니다. 당신 위에는 ​​아무것도 없습니다. 당신은 숨겨진 존재입니다. 당신에게서 숨겨진 것은 아무것도 없습니다. 우리의 빚을 청산해 주시고 우리를 가난에서 구해 주십시오.", "잠들기 전, 오른쪽으로 누워 있음 - 파티마에게 가르쳤음 (RA).", "빚과 고난으로부터 구제하기 위한 이중입니다."),
        "dua_sleep_fear" to DuaText("수면 중 두려움이나 불안", "나는 알라의 분노와 형벌, 그의 종들의 악함, 악마의 속삭임, 그리고 그들이 나에게 오는 것으로부터 피난처를 구합니다.", "잠잘 때 두려움이나 불안감을 느낄 때.", "그렇게 하면 그 일이 그 사람에게 해를 끼치지 않을 것이다."),
        "dua_waking_afani" to DuaText("깨어남: 그는 내 영혼을 회복시켰습니다", "모든 찬양은 내 몸의 안녕을 주시고, 내 영혼을 나에게 돌려주시고, 내가 그분을 기억할 수 있게 해주신 알라께 대한 것입니다.", "깨어날 때.", "새로운 아침에 감사드립니다."),
        "dua_allahu_rabbi" to DuaText("알라, 알라는 나의 주님이시다", "알라, 알라는 나의 주님이십니다. 나는 그와 어떤 것도 연관시키지 않습니다.", "슬픔이나 괴로움 속에서 예언자 ﷺ은 이를 Asma bint Umays (RA)에게 가르쳤습니다.", "고난의 시기에 타우히드를 붙잡습니다."),
        "dua_rahmataka_arju" to DuaText("내가 바라는 당신의 자비", "오 알라, 내가 바라는 것은 당신의 자비이오니, 잠시라도 나를 혼자 두지 마시고 내 모든 일을 바로잡아 주소서. 당신 외에는 신이 없습니다.", "고난에 처한 자의 두아(Da'awat al-makrub).", "선지자 ﷺ은 그것을 곤경에 처한 자의 듀아라고 불렀습니다."),
        "dua_against_enemy_ahzab" to DuaText("적군에 맞서", "오 알라, 책의 계시자, 계산이 신속하시도다! 동맹을 물리치세요. 오 알라여, 그들을 물리치고 흔들어 주시옵소서.", "적에 맞서는 것은 남부연합 전투의 두아입니다.", "적에 대한 예언자의 ﷺ dua."),
        "dua_anta_adudi" to DuaText("당신은 나의 지지자입니다", "오 알라, 당신은 나의 지지자이자 도우미입니다. 나는 당신에 의해 계획하고, 당신에 의해 전진하며, 당신에 의해 싸웁니다.", "콘테스트나 주요 도전 전.", "예언자 ﷺ은 전투에서 이렇게 말했습니다."),
        "dua_ikfinihim" to DuaText("그들에 맞서면 충분해", "오 알라시여, 당신의 뜻대로 저들로 충분하리이다.", "억압자의 악에 맞서는 것은 도랑의 사람들 이야기에 나오는 소년의 이중입니다.", "알라는 압제자들로부터 소년을 구해냈습니다."),
        "dua_qadarullah" to DuaText("나쁜 일이 일어날 때", "이것은 알라의 명령이며 그분은 뜻하신 일을 행하셨습니다.", "불쾌한 일이 일어났을 때 '만약'이라고 말하는 대신.", "'만약'은 샤이탄에게 문을 열어준다."),
        "dua_ala_kulli_hal" to DuaText("어떤 상황에서도 찬양하라", "모든 상황에서 모든 찬양은 알라를 위한 것입니다.", "싫어하는 일이 일어났을 때.", "예언자 ﷺ은 자신이 싫어하는 일에 직면했을 때 이렇게 말했습니다."),
        "dua_dogs_barking" to DuaText("밤에 개가 짖는 소리를 듣는다", "나는 저주받은 자 샤이탄에게서 알라께 피난처를 구합니다.", "밤에 개가 짖는 소리나 당나귀가 우는 소리를 들으면.", "그들은 당신이 보지 못하는 것을 봅니다."),
        "dua_leaving_home_adilla" to DuaText("길을 잃지 않도록 피난처", "오 알라, 나는 당신께 피난처를 구합니다. 내가 길을 잃지 않도록, 잘못된 길로 인도되지 않도록, 미끄러지거나 미끄러지지 않도록, 내가 나쁜 일을 하거나 잘못을 당하지 않도록, 어리석게 행동하거나 어리석은 대우를 받지 않도록 말입니다.", "집을 떠날 때 — Umm Salamah (RA) 내레이션.", "선지자 ﷺ은 집을 떠날 때마다 이것을 낭송했습니다."),
        "dua_ascending_descending" to DuaText("올라가고 내려오는", "알라는 가장 위대하다 (올라갈 때). — 알라에게 영광이 있기를(내려올 때)", "여행 중에 올라갈 때는 '알라후 아크바르(Allahu Akbar)'라고 말하고 내려올 때는 '수반알라(SubhanAllah)'라고 말하세요.", "여행 중 동행자들의 실천 (RA)."),
        "dua_traveller_sahar" to DuaText("새벽 전의 여행자 두아", "한 청취자가 알라에 대한 우리의 찬양과 우리에게 베푸시는 그분의 은총을 듣고 전했습니다. 우리 주님, 우리와 동행하시고 우리에게 당신의 은총을 베푸소서. (내가 이것을 말하노니) 불로부터 알라께 피난처를 구하소서.", "여행 중, 새벽이 되기 전에.", "선지자 ﷺ은 여행 중에 새벽이 되기 전에 이렇게 말했습니다."),
        "dua_zawwadakallah" to DuaText("여행자에게: 알라께서 Taqwa를 제공하시기를 바랍니다", "알라께서 당신의 여행을 위해 타콰(taqwa)를 제공하시고, 당신의 죄를 용서하시고, 당신이 어디에 있든 쉽게 좋은 일을 하시기를 빕니다.", "여행자에게 작별 인사를 할 때.", "예언자 ﷺ은 여행을 떠나는 누군가에게 이 두아를 주었습니다."),
        "dua_traveller_to_resident" to DuaText("뒤에 남아 있는 사람들을 위한 여행자", "나는 결코 신뢰를 잃지 않으시는 알라께 당신을 맡깁니다.", "여행자가 가족에게 작별 인사를 할 때 한 말입니다.", "가족의 안전을 알라께 맡깁니다."),
        "dua_entering_village" to DuaText("마을이나 마을에 들어가기", "오 알라, 일곱 하늘과 그늘진 모든 것의 주인이시요, 일곱 땅과 그들이 가지고 있는 모든 것의 주인이시며, 악마와 그들이 그릇 인도하는 모든 것의 주인이시며, 바람과 그들이 흩어뜨리는 모든 것의 주인이시니이다! 우리는 당신께 이 마을과 그 사람들의 행복을 구하며, 이 도시의 악과 그 사람들의 악과 그 안에 있는 모든 것의 악으로부터 당신께 피난처를 구합니다.", "마을이나 도시에 들어가기 전.", "예언자 ﷺ은 마을에 들어가고 싶을 때마다 이 말을 낭송했습니다."),
        "dua_vehicle_stumbles" to DuaText("차량이 비틀거릴 때", "알라의 이름으로.", "탈것이나 차량이 미끄러지거나 넘어졌을 때 '샤이탄이 멸망하길'이라고 말하는 대신.", "Bismillah라고 말하면 Shaytan은 파리 크기로 줄어 듭니다."),
        "dua_ajz_kasal_haram" to DuaText("약점과 노년으로부터의 피난처", "오 알라, 나는 무력함과 게으름, 비겁함과 노년, 삶과 죽음의 시련, 무덤의 형벌로부터 당신께 피난처를 구합니다.", "포괄적인 일일 피난처 듀오입니다.", "예언자 ﷺ이 자주 만든 듀아."),
    )
}
